mapper.select:
SELECT DPB.SETT_DATE, PINDEX.UNIT_VALUE_T lastUnitValueT FROM
	REP_PROD_INFO INFO
INNER JOIN DIS_PROD_BONUSPLAN DPB  ON DPB.PROD_ID=INFO.PROD_ID AND DPB.DATA_STATUS='E'
INNER JOIN REP_PROD_INDEX_GZ PINDEX ON PINDEX.PROD_ID=INFO.PROD_ID AND PINDEX.STATUS='E' AND PINDEX.VALUE_DATE=DPB.SETT_DATE
WHERE DPB.DATA_STATUS = 'E'
  AND INFO.PROD_ID = #{prodId,jdbcType=VARCHAR}
  AND DPB.SETT_DATE = (
	  select max(h.SETT_DATE) from DIS_PROD_BONUSPLAN h
	  where h.SETT_DATE < #{baseDate}

			and h.SETT_DATE > #{setDate}

		and h.PROD_ID = #{prodId,jdbcType=VARCHAR}
		and h.DATA_STATUS = 'E'
	)

SELECT TO_CHAR(DPP.OPEN_START_DATE,'yyyy-MM-dd') openStartDate,TO_CHAR(DPP.OPEN_START_DATE,'yyyy-MM-dd')||'至'||TO_CHAR(DPP.OPEN_END_DATE,'yyyy-MM-dd') nextRange,TO_CHAR(DPP.OPEN_END_DATE,'yyyy-MM-dd') nextMdate FROM REP_PROD_INFO INFO,DIS_PROD_PLAN DPP WHERE INFO.STATUS = 'E' AND DPP.PROD_ID = NVL(INFO.P_PROD_ID,INFO.PROD_ID) AND DPP.OPEN_START_DATE>TO_DATE(#{baseDate},'yyyy-MM-dd')
AND DPP.OPEN_START_DATE > #{setDate}
AND INFO.PROD_ID = #{prodId,jdbcType=VARCHAR} ORDER BY DPP.OPEN_END_DATE

SELECT PINDEX.ASSETS_VALUE /**资产净值**/ ,PINDEX.CAPITAL /**期末余额**/ ,PLAN.SETT_DATE /*基准日*/ ,PLAN.PAYMENT_DATE /*红利发放日*/ ,DPP.OPEN_START_DATE /*开放起始日*/ ,DPP.OPEN_END_DATE /*开放结束日*/ ,TO_CHAR(DPP.OPEN_END_DATE,'yyyy-MM-dd') curBaseDate ,TO_CHAR(DPP.OPEN_START_DATE,'yyyy-MM-dd')||'至'||TO_CHAR(DPP.OPEN_END_DATE,'yyyy-MM-dd') curRange ,PLAN.ACHIEVEMENT_BASIS_PROP ,PLAN.EXCESS_ACHIEVEMENT_PROP FROM REP_PROD_INFO INFO INNER JOIN DIS_PROD_PLAN DPP ON DPP.PROD_ID = NVL(INFO.P_PROD_ID,INFO.PROD_ID) AND DPP.OPEN_END_DATE <=TO_DATE(#{baseDate},'yyyy-MM-dd')
AND DPP.OPEN_START_DATE > #{setDate}
INNER JOIN REP_PROD_INDEX_GZ PINDEX ON PINDEX.PROD_ID=INFO.PROD_ID AND PINDEX.STATUS='E' AND PINDEX.VALUE_DATE=DPP.OPEN_END_DATE INNER JOIN DIS_PROD_BONUSPLAN PLAN ON PLAN.PROD_ID=INFO.PROD_ID AND PLAN.DATA_STATUS='E' AND PLAN.SETT_DATE=DPP.OPEN_END_DATE WHERE INFO.STATUS='E' AND INFO.PROD_ID=#{prodId,jdbcType=VARCHAR} ORDER BY DPP.OPEN_END_DATE DESC

SELECT PLAN.SETT_DATE /*基准日*/ ,PLAN.PAYMENT_DATE /*红利发放日*/ FROM REP_PROD_INFO INFO INNER JOIN DIS_PROD_BONUSPLAN PLAN ON PLAN.PROD_ID=INFO.PROD_ID AND PLAN.DATA_STATUS='E' AND PLAN.SETT_DATE=TO_DATE(#{baseDate},'yyyy-MM-dd')
AND PLAN.SETT_DATE > #{setDate}
AND PLAN.BONUS_MODE = '01' WHERE INFO.STATUS='E' AND INFO.PROD_ID=#{prodId,jdbcType=VARCHAR}
